export function useGoBack() {
  const history =
    typeof ReactRouterDOM.useHistory === 'function'
      ? ReactRouterDOM.useHistory()
      : null
  const navigate =
    typeof ReactRouterDOM.useNavigate === 'function'
      ? ReactRouterDOM.useNavigate()
      : null

  return () => {
    if (history?.goBack) {
      history.goBack()
      return
    }

    navigate(-1)
  }
}

