import React from 'react'
import * as ReactRouterDOM from 'react-router-dom'

const routes = ReactRouterDOM['Routes']
const navigate = ReactRouterDOM['Navigate']
const isV6 = typeof routes === 'function'

export const { BrowserRouter, Link, MemoryRouter, NavLink, useLocation } =
  ReactRouterDOM

export const Navigate = isV6
  ? navigate
  : function Navigate({ to }) {
      return <ReactRouterDOM.Redirect to={to} />
    }

export const Route = isV6
  ? ReactRouterDOM.Route
  : function Route({ element, ...props }) {
      return <ReactRouterDOM.Route {...props} render={() => element} />
    }

export const Routes = isV6
  ? routes
  : function Routes({ children }) {
      return <ReactRouterDOM.Switch>{children}</ReactRouterDOM.Switch>
    }

function callRouterHook(name, ...args) {
  const hook = ReactRouterDOM[name]

  return typeof hook === 'function' ? hook(...args) : null
}

export function useMatch(pattern) {
  return (
    callRouterHook('useMatch', pattern) ||
    callRouterHook('useRouteMatch', pattern)
  )
}

export function useParams() {
  return (
    callRouterHook('useParams') || callRouterHook('useRouteMatch')?.params || {}
  )
}

export function useGoBack() {
  const history = callRouterHook('useHistory')
  const navigate = callRouterHook('useNavigate')

  return () => {
    if (history?.goBack) {
      history.goBack()
      return
    }

    navigate(-1)
  }
}
